const digest=(algorithm,body)=>crypto.createHash(algorithm).update(body).digest('hex');
const blob=b=>digest('sha1',Buffer.concat([Buffer.from('blob '+b.length+'\0'),b]));
function identity(body,record,label){
  const b=Buffer.isBuffer(body)?body:Buffer.from(body,'utf8');
  if(b.length!==record.bytes||digest('sha256',b)!==record.sha256||blob(b)!==record.git_blob_sha)
    throw new Error('Whole source identity mismatch: '+label);
  const text=b.toString('utf8');
  if(!Buffer.from(text,'utf8').equals(b))throw new Error('Non-UTF-8 source: '+label);
  return text;
}
function resolveInside(root,relative){
  if(typeof relative!=='string'||!relative.startsWith(DATA.topic+'/')||relative.includes('\\'))
    throw new Error('Expected complete repository-relative topic source path');
  const out=path.resolve(root,relative),prefix=root+path.sep;
  if(!out.startsWith(prefix))throw new Error('Source path escapes repository');
  return out;
}
function applyPatch(text,p,inverse){
  const before=inverse?p.to:p.from,after=inverse?p.from:p.to;
  const offsets=inverse?p.after_character_offsets:p.before_character_offsets;
  if(!before||offsets.length!==p.count||!Number.isSafeInteger(p.count)||p.count<1)
    throw new Error('Invalid complete textual patch');
  if(!inverse&&text.split(before).length-1!==p.count)
    throw new Error('Complete forward literal count differs');
  for(let j=offsets.length-1;j>=0;j--){
    const at=offsets[j];
    if(!Number.isSafeInteger(at)||at<0||text.slice(at,at+before.length)!==before)
      throw new Error('Exact complete-source patch location differs');
    text=text.slice(0,at)+after+text.slice(at+before.length);
  }
  return text;
}
function writeWhole(file,body,record){
  const b=Buffer.from(body,'utf8');
  identity(b,record,file);
  fs.mkdirSync(path.dirname(file),{recursive:true});
  if(fs.existsSync(file)){identity(fs.readFileSync(file),record,file);return 'existing-identical-whole-source';}
  const temporary=file+'.complete-source-build-'+process.pid;
  fs.writeFileSync(temporary,b,{flag:'wx',mode:0o644});
  fs.renameSync(temporary,file);
  identity(fs.readFileSync(file),record,file);
  return 'materialized-complete-source';
}
